"""Click-based CLI entry point for the `notes` tool."""
import click

from . import storage


@click.group()
def cli() -> None:
    """Manage notes with optional BibTeX citations."""


@cli.command()
@click.option("--title", required=True, help="Note title.")
@click.option("--body", required=True, help="Note body text.")
@click.option(
    "--tags",
    multiple=True,
    help="Tag to attach to the note. Repeat for multiple tags.",
)
@click.option(
    "--citation",
    default=None,
    help="Optional citation in BibTeX format.",
)
@click.option(
    "--priority",
    type=click.IntRange(1, 5),
    default=3,
    show_default=True,
    help="Priority of the note (1-5).",
)
def add(title: str, body: str, tags: tuple, citation: str, priority: int) -> None:
    """Add a new note."""
    note = storage.save_note(
        title=title,
        body=body,
        tags=list(tags),
        citation=citation,
        priority=priority,
    )
    click.echo(f"Added note {note['id']}: {note['title']}")


@cli.command()
def ls() -> None:
    """List all notes with their id and title."""
    for note in storage.list_notes():
        click.echo(f"{note['id']}\t{note['title']}")


@cli.command()
@click.argument("note_id", type=int)
def show(note_id: int) -> None:
    """Print the full contents of one note."""
    note = storage.load_note(note_id)
    if note is None:
        raise click.ClickException(f"No note with id {note_id}")
    click.echo(f"id: {note['id']}")
    click.echo(f"title: {note['title']}")
    click.echo(f"tags: {', '.join(note.get('tags', []))}")
    if note.get("citation"):
        click.echo(f"citation: {note['citation']}")
    click.echo("")
    click.echo(note["body"])


@cli.command()
@click.argument("note_id", type=int)
def rm(note_id: int) -> None:
    """Delete a note by id."""
    if not storage.delete_note(note_id):
        raise click.ClickException(f"No note with id {note_id}")
    click.echo(f"Deleted note {note_id}")


@cli.command()
@click.argument("query")
def search(query: str) -> None:
    """Substring match against title and body, case-insensitive."""
    needle = query.lower()
    for note in storage.list_notes():
        if needle in note["title"].lower() or needle in note["body"].lower():
            click.echo(f"{note['id']}\t{note['title']}")


@cli.command("filter-by-tag")
@click.argument("tag")
def filter_by_tag(tag: str) -> None:
    """Print the SUBSET of notes whose tags contain TAG."""
    for note in storage.list_notes():
        if tag in note.get("tags", []):
            click.echo(f"{note['id']}\t{note['title']}")


@cli.command("sort-by-tag")
def sort_by_tag() -> None:
    """Print ALL notes, sorted alphabetically by their first tag."""
    notes = storage.list_notes()
    notes.sort(key=lambda n: n["tags"][0] if n.get("tags") else "")
    for note in notes:
        click.echo(f"{note['id']}\t{note['title']}")


@cli.command("col-create")
@click.argument("name")
def col_create(name: str) -> None:
    """Create an empty collection named NAME."""
    try:
        collection = storage.create_collection(name)
    except ValueError as exc:
        raise click.ClickException(str(exc))
    click.echo(f"Created collection {collection['name']}")


@cli.command("col-ls")
def col_ls() -> None:
    """List all collections with their sizes."""
    for collection in storage.list_collections():
        click.echo(f"{collection['name']}\t{len(collection['note_ids'])}")


@cli.command("col-show")
@click.argument("name")
def col_show(name: str) -> None:
    """Print the notes in a collection."""
    collection = storage.load_collection(name)
    if collection is None:
        raise click.ClickException(f"no collection named {name!r}")
    for note_id in collection["note_ids"]:
        note = storage.load_note(note_id)
        if note is None:
            continue
        click.echo(f"{note['id']}\t{note['title']}")


@cli.command("col-rm")
@click.argument("name")
def col_rm(name: str) -> None:
    """Delete a collection (the underlying notes are kept)."""
    if not storage.delete_collection(name):
        raise click.ClickException(f"no collection named {name!r}")
    click.echo(f"Deleted collection {name}")


@cli.command("col-add")
@click.argument("collection_name")
@click.argument("note_id", type=int)
def col_add(collection_name: str, note_id: int) -> None:
    """Add NOTE_ID to COLLECTION_NAME."""
    try:
        storage.add_note_to_collection(collection_name, note_id)
    except ValueError as exc:
        raise click.ClickException(str(exc))
    click.echo(f"Added note {note_id} to collection {collection_name}")

