    collections = storage.list_collections()
    if by == "name":
        collections.sort(key=lambda c: c["name"])
    elif by == "size":
        collections.sort(key=lambda c: len(c["note_ids"]))
    else:  # created
        collections.sort(key=lambda c: c["created"])
